def bus_timer(current_time):
    from datetime import datetime, timedelta

    current = datetime.strptime(current_time, "%H:%M")
    first_bus = datetime.strptime("06:00", "%H:%M")
    last_bus = datetime.strptime("00:00", "%H:%M")

    if current >= last_bus:
        first_bus += timedelta(days=1)

    while current > first_bus:
        first_bus += timedelta(minutes=15)

    wait_time = (first_bus - current).seconds // 60 - 5

    return max(wait_time, 0)
